from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,zipfile
R=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):
    with p.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def main():
    out=R/'results/dynamic_root_checkpoint_v1.json';assert not out.exists();p=R/'snapshots/after_dynamic_root_v1.zip';m=read(p.with_suffix('.manifest.json'));assert sha(p)==m['archive_sha256'];c=read(R/'results/latex_compile_status_v35.json');assert c['kind']=='success' and sha(R/'median_depth_note.tex')==c['source_sha256'];g=read(R/'results/canvas_dynamic_root_guard_v1.json');assert sha(Path(g['destination']))==g['staged_sha256'] and not read(R/'results/canvas_dynamic_root_syntax_v1.json')['errors']
    s=read(R/'experiments/dynamic_root_v1/summary.json');a=read(R/'results/dynamic_root_audit_v1.json');rare=read(R/'results/dynamic_root_rare_audit_v1.json');ra=read(R/'results/dynamic_root_rare_artifacts_v1.json');assert s['status']=='complete' and a['gate_pass'] and rare['gate_pass'] and ra['gate_pass'] and s['totals']['certified']==562079 and s['totals']['no_finite_root']==256 and s['totals']['unresolved']==0
    names=['research/dynamic_root.cuh','research/dynamic_root_cuda.py','research/benchmark_dynamic_root.py','research/verify_dynamic_root.py','research/DYNAMIC_ROOT_PROTOCOL.md','research/DYNAMIC_ROOT_RESULT.md','research/experiments/dynamic_root_v1/summary.json','research/experiments/dynamic_root_v1/scan55_0000_probes.npz','research/experiments/dynamic_root_v1/scan55_0000_output.npz','research/results/dynamic_root_audit_v1.json','research/results/dynamic_root_rare_audit_v1.json','research/experiments/dynamic_root_rare_v1/scan37_0020_probes.npz','research/median_depth_note.tex','research/results/latex_compile_status_v35.json','research/canvas_result_snapshot.tsx']
    with zipfile.ZipFile(p) as z:
        assert json.loads(z.read('SNAPSHOT_MANIFEST.json'))['files_sha256']==m['files_sha256']
        for n in names:assert hashlib.sha256(z.read(n)).hexdigest()==m['files_sha256'][n]
    result=dict(status='current_step_complete',checked_utc=datetime.now(timezone.utc).isoformat(),overall_goal_achieved=False,previous_goal_turn_classification='progress: full original-depth sufficient conditions and independent complete-ray probes',current_goal_turn_classification='progress: all562335 unresolved original-valid actual rays dynamically solved/classified, fixed891 probes and entire299 rare-branch union independently verified',totals=s['totals'],certificates={str(k):sum(r['certificates'][str(k)] for r in s['rows']) for k in [1,2,3]},world_probe_rays=891,world_probe_nodes=51524,world_MP_coefficient_checks=206096,entire_rare_union_rays=299,rare_MP_coefficient_checks=23680,all256_no_finite_root_independent_confirmation=True,all9_original_anomalies_certified=True,terminal_handles=dict(main_session88413=0,independent_session23351=0,rare_session36155=0,rare_artifact_checker=0),source_latex_matches_builtin_success=True,source_canvas_matches_syntax_checked_stage=True,snapshot=dict(sha256=m['archive_sha256'],files=len(m['files_sha256']),bytes=p.stat().st_size,selected_member_checks=names),limits=['Original no-candidate/ineligible pixels not filled; finite root certification is model mathematical accuracy, not GT quality.','Dynamic low/high root events5.822–204.906ms/view; first decode3258.099ms retained; no whole pipeline acceleration.','Source world-VJP/fullGT/training/novelty incomplete; canvas syntax only, SDK/runtime unverified.'],next='Use persisted source/internal certified roots to audit chain-rule VJP and conditioning; run frozen-model complete reconstruction GT contrasts before training adoption. Do not rerun completed full numerical diagnostics.')
    out.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({k:v for k,v in result.items() if k not in ['limits','next']},indent=2))
if __name__=='__main__':main()
